contract_clause_fact(contrato_ocs_0044_2022, clausula_setima_pagamento, prazo_pagamento, '30 dias', 'trecho_literal').
contract_clause_fact(contrato_ocs_0044_2022, clausula_setima_pagamento, prazo_pagamento, '10 dias úteis', 'trecho_literal').
